class DetectionsPage{constructor(){this.detections=[];this.filteredDetections=[];this.currentFilters={search:'',camera:'',confidence:'',dateFrom:'',dateTo:'',status:'',direction:'',speedMin:'',speedMax:''};this.currentSort={column:null,direction:null};this.selectedDetections=new Set();this.pagination={page:1,limit:50,total:0};this.init();}init(){this.loadMockData();this.render();this.attachEventListeners();this.updateTable();}loadMockData(){this.detections=[{id:'det_001',plate_number:'ABC-123',camera_id:'cam_001',camera_name:'Entrance Gate',confidence:98.5,timestamp:new Date(),vehicle_type:'Sedan',vehicle_color:'Blue',vehicle_make:'Toyota',vehicle_model:'Camry',status:'verified',flagged:false,direction:'entering',speed:25,image_path:'/images/det_001.jpg',processing_time:234,coordinates:{x:120,y:45,width:150,height:80}},{id:'det_002',plate_number:'XYZ-789',camera_id:'cam_002',camera_name:'Parking Lot A',confidence:87.2,timestamp:new Date(Date.now()-5*60*1000),vehicle_type:'SUV',vehicle_color:'White',vehicle_make:'Honda',vehicle_model:'CR-V',status:'flagged',flagged:true,direction:'parking',speed:12,image_path:'/images/det_002.jpg',processing_time:187,coordinates:{x:85,y:32,width:140,height:75}},{id:'det_003',plate_number:'DEF-456',camera_id:'cam_003',camera_name:'Loading Dock',confidence:92.8,timestamp:new Date(Date.now()-15*60*1000),vehicle_type:'Truck',vehicle_color:'Red',vehicle_make:'Ford',vehicle_model:'F-150',status:'verified',flagged:false,direction:'exiting',speed:18,image_path:'/images/det_003.jpg',processing_time:312,coordinates:{x:95,y:28,width:165,height:85}},];this.filteredDetections=[...this.detections];this.pagination.total=this.detections.length;}render(){const container=document.getElementById('detections');if(!container)return;container.innerHTML=this.getTemplate();}getTemplate(){return ` <div class="page-header"> <h1 class="page-title">Detection Results</h1> <p class="page-subtitle">License plate detection history and analysis</p> </div> <!--Detection Action Bar--> <div class="detection-action-bar"> <button class="btn btn-primary" id="export-csv-btn"> <i class="fas fa-file-csv"></i> Export CSV </button> <button class="btn btn-primary" id="export-pdf-btn"> <i class="fas fa-file-pdf"></i> Export PDF </button> <button class="btn btn-secondary" id="manual-detection-btn"> <i class="fas fa-search"></i> Manual Detection </button> <button class="btn btn-secondary" id="detection-report-btn"> <i class="fas fa-chart-bar"></i> Detection Report </button> </div> <!--Detection Filters--> <div class="detection-filters"> <!--Filter Row 1--> <div class="filter-row filter-row-1"> <div class="filter-group smart-search-group"> <label for="smart-search">Smart Search:</label> <input type="text" id="smart-search" class="filter-input smart-search-input" placeholder="🔍 License plate,vehicle type,color..." value="${this.currentFilters.search}"> </div> <div class="filter-group quick-filters-group"> <label>Quick Time:</label> <div class="quick-filter-row"> <button class="quick-filter-btn" data-period="1h">Last Hour</button> <button class="quick-filter-btn" data-period="24h">Last 24h</button> <button class="quick-filter-btn" data-period="today">Today</button> <button class="quick-filter-btn" data-period="yesterday">Yesterday</button> </div> </div> <div class="filter-group date-range-group"> <label>Date Range:</label> <div class="date-inputs"> <input type="date" id="date-from" class="filter-input date-input" value="${this.currentFilters.dateFrom}"> <input type="date" id="date-to" class="filter-input date-input" value="${this.currentFilters.dateTo}"> </div> </div> <div class="filter-group"> <label>Camera:</label> <select id="camera-filter" class="filter-select"> <option value="">All Cameras</option> <option value="cam_001">Entrance Gate</option> <option value="cam_002">Parking Lot A</option> <option value="cam_003">Loading Dock</option> <option value="cam_004">Side Entrance</option> <option value="cam_005">Rear Exit</option> <option value="cam_006">Visitor Parking</option> </select> </div> </div> <!--Filter Row 2--> <div class="filter-row filter-row-2"> <div class="filter-group direction-speed-group"> <div class="filter-subgroup"> <label>Direction:</label> <select id="direction-filter" class="filter-select compact"> <option value="">All Directions</option> <option value="entering">Entering</option> <option value="exiting">Exiting</option> <option value="parking">Parking</option> <option value="loading">Loading</option> </select> </div> <div class="filter-subgroup speed-range-subgroup"> <label>Speed(mph):</label> <div class="range-inputs"> <input type="number" id="speed-min" class="filter-input range-input" placeholder="Min" min="0" max="100" value="${this.currentFilters.speedMin}"> <span class="range-separator">-</span> <input type="number" id="speed-max" class="filter-input range-input" placeholder="Max" min="0" max="100" value="${this.currentFilters.speedMax}"> </div> </div> </div> <div class="filter-group quick-filters-group"> <label>Extended Time:</label> <div class="quick-filter-row"> <button class="quick-filter-btn" data-period="this-week">This Week</button> <button class="quick-filter-btn" data-period="last-week">Last Week</button> <button class="quick-filter-btn" data-period="30d">Last 30 Days</button> </div> </div> <div class="filter-group confidence-status-group"> <div class="filter-subgroup"> <label>Confidence:</label> <select id="confidence-filter" class="filter-select compact"> <option value="">All Confidence</option> <option value="high">High(90%+)</option> <option value="medium">Medium(70-89%)</option> <option value="low">Low(<70%)</option> </select> </div> <div class="filter-subgroup"> <label>Status:</label> <select id="status-filter" class="filter-select compact"> <option value="">All Status</option> <option value="verified">Verified</option> <option value="flagged">Flagged</option> <option value="pending">Pending</option> </select> </div> </div> <div class="filter-actions"> <button class="btn btn-primary" id="apply-filters-btn">Apply Filters</button> <button class="btn btn-secondary" id="clear-all-filters-btn">Clear All</button> </div> </div> </div> <!--Detection Results--> <div class="detection-results-container"> <div class="detection-table-header"> <h3>Detection Results(${this.filteredDetections.length})</h3> <div class="bulk-actions" id="bulk-actions" style="display:none;"> <button class="btn btn-small btn-secondary" id="bulk-verify">Verify Selected</button> <button class="btn btn-small btn-warning" id="bulk-flag">Flag Selected</button> <button class="btn btn-small btn-danger" id="bulk-delete">Delete Selected</button> </div> </div> <div class="detection-table-wrapper"> <table class="detection-table" id="detection-table"> <thead> <tr> <th class="checkbox-column"> <input type="checkbox" id="select-all-detections"> </th> <th class="sortable" data-sort="timestamp"> Timestamp <i class="fas fa-sort sort-icon"></i> </th> <th class="sortable" data-sort="plate"> Plate Number <i class="fas fa-sort sort-icon"></i> </th> <th class="sortable" data-sort="camera"> Camera <i class="fas fa-sort sort-icon"></i> </th> <th class="sortable" data-sort="confidence"> Confidence <i class="fas fa-sort sort-icon"></i> </th> <th class="sortable" data-sort="vehicle"> Vehicle <i class="fas fa-sort sort-icon"></i> </th> <th class="sortable" data-sort="status"> Status <i class="fas fa-sort sort-icon"></i> </th> <th class="actions-column">Actions</th> </tr> </thead> <tbody id="detection-table-body"> <!--Detection rows will be dynamically loaded--> </tbody> </table> </div> <div class="detection-pagination" id="detection-pagination"> <!--Pagination will be dynamically loaded--> </div> </div> <!--Detection Details Modal--> <div class="modal-overlay" id="detection-details-modal" style="display:none;"> <div class="modal-container detection-details-container"> <div class="modal-header"> <div class="modal-title"> <i class="fas fa-search"></i> <span>Detection Details-<span id="modal-plate-number">ABC-123</span></span> </div> <button class="modal-close" id="close-detection-modal"> <i class="fas fa-times"></i> </button> </div> <div class="modal-content"> <div class="detection-details-layout"> <!--Left side-Vehicle Image--> <div class="detection-image-section"> <div class="vehicle-image-container"> <div class="vehicle-image" id="modal-vehicle-image"> <i class="fas fa-car"></i> <div class="plate-overlay"> <span class="plate-text" id="modal-plate-overlay">ABC-123</span> </div> </div> </div> <div class="image-actions"> <button class="btn btn-small btn-secondary" id="enhanced-image-btn"> <i class="fas fa-magic"></i> Enhanced Image </button> <button class="btn btn-small btn-secondary" id="video-clip-btn"> <i class="fas fa-video"></i> Video Clip </button> </div> </div> <!--Right side-Detection Information--> <div class="detection-info-section"> <div class="detection-tabs"> <button class="detection-tab active" data-tab="basic">Basic Info</button> <button class="detection-tab" data-tab="vehicle">Vehicle Details</button> <button class="detection-tab" data-tab="confidence">Confidence Analysis</button> </div> <div class="detection-tab-content"> <!--Basic Info Tab--> <div class="tab-panel active" id="basic-tab"> <div class="info-grid" id="basic-info-grid"> <!--Dynamic content--> </div> </div> <!--Vehicle Details Tab--> <div class="tab-panel" id="vehicle-tab"> <div class="info-grid" id="vehicle-info-grid"> <!--Dynamic content--> </div> </div> <!--Confidence Analysis Tab--> <div class="tab-panel" id="confidence-tab"> <div class="confidence-breakdown" id="confidence-breakdown"> <!--Dynamic content--> </div> </div> </div> </div> </div> </div> <div class="modal-footer"> <button class="btn btn-warning" id="flag-detection-btn"> <i class="fas fa-flag"></i> Flag Detection </button> <button class="btn btn-success" id="download-detection-btn"> <i class="fas fa-download"></i> Download </button> <button class="btn btn-secondary" id="close-modal-btn"> <i class="fas fa-times"></i> Close </button> </div> </div> </div> `;}attachEventListeners(){document.getElementById('smart-search')?.addEventListener('input',this.debounce((e)=> this.handleSearch(e.target.value),300));document.querySelectorAll('.quick-filter-btn').forEach(btn=>{btn.addEventListener('click',(e)=> this.handleQuickFilter(e.target.dataset.period));});document.getElementById('camera-filter')?.addEventListener('change',(e)=> this.updateFilter('camera',e.target.value));document.getElementById('confidence-filter')?.addEventListener('change',(e)=> this.updateFilter('confidence',e.target.value));document.getElementById('status-filter')?.addEventListener('change',(e)=> this.updateFilter('status',e.target.value));document.getElementById('direction-filter')?.addEventListener('change',(e)=> this.updateFilter('direction',e.target.value));document.getElementById('date-from')?.addEventListener('change',(e)=> this.updateFilter('dateFrom',e.target.value));document.getElementById('date-to')?.addEventListener('change',(e)=> this.updateFilter('dateTo',e.target.value));document.getElementById('speed-min')?.addEventListener('input',(e)=> this.updateFilter('speedMin',e.target.value));document.getElementById('speed-max')?.addEventListener('input',(e)=> this.updateFilter('speedMax',e.target.value));document.getElementById('apply-filters-btn')?.addEventListener('click',()=> this.applyFilters());document.getElementById('clear-all-filters-btn')?.addEventListener('click',()=> this.clearAllFilters());document.getElementById('export-csv-btn')?.addEventListener('click',()=> this.exportCSV());document.getElementById('export-pdf-btn')?.addEventListener('click',()=> this.exportPDF());document.querySelectorAll('.sortable').forEach(header=>{header.addEventListener('click',()=> this.handleSort(header.dataset.sort));});document.getElementById('select-all-detections')?.addEventListener('change',(e)=> this.handleSelectAll(e.target.checked));document.getElementById('close-detection-modal')?.addEventListener('click',()=> this.closeModal());document.getElementById('close-modal-btn')?.addEventListener('click',()=> this.closeModal());document.querySelectorAll('.detection-tab').forEach(tab=>{tab.addEventListener('click',(e)=> this.switchTab(e.target.dataset.tab));});}debounce(func,wait){let timeout;return function executedFunction(...args){const later=()=>{clearTimeout(timeout);func(...args);};clearTimeout(timeout);timeout=setTimeout(later,wait);};}handleSearch(query){this.currentFilters.search=query;this.applyFilters();}handleQuickFilter(period){document.querySelectorAll('.quick-filter-btn').forEach(btn=> btn.classList.remove('active'));event.target.classList.add('active');const now=new Date();let dateFrom='';switch(period){case '1h':dateFrom=new Date(now.getTime()-60*60*1000);break;case '24h':dateFrom=new Date(now.getTime()-24*60*60*1000);break;case 'today':dateFrom=new Date(now.getFullYear(),now.getMonth(),now.getDate());break;case 'yesterday':dateFrom=new Date(now.getFullYear(),now.getMonth(),now.getDate()-1);break;case 'this-week':dateFrom=new Date(now.getTime()-7*24*60*60*1000);break;case 'last-week':dateFrom=new Date(now.getTime()-14*24*60*60*1000);break;case '30d':dateFrom=new Date(now.getTime()-30*24*60*60*1000);break;}if(dateFrom){this.currentFilters.dateFrom=dateFrom.toISOString().split('T')[0];document.getElementById('date-from').value=this.currentFilters.dateFrom;this.applyFilters();}}updateFilter(key,value){this.currentFilters[key]=value;this.applyFilters();}applyFilters(){this.filteredDetections=this.detections.filter(detection=>{if(this.currentFilters.search){const search=this.currentFilters.search.toLowerCase();const searchable=`${detection.plate_number}${detection.vehicle_color}${detection.vehicle_type}${detection.vehicle_make}${detection.vehicle_model}${detection.camera_name}`.toLowerCase();if(!searchable.includes(search))return false;}if(this.currentFilters.camera && detection.camera_id !==this.currentFilters.camera){return false;}if(this.currentFilters.confidence){const confidence=detection.confidence;switch(this.currentFilters.confidence){case 'high':if(confidence < 90)return false;break;case 'medium':if(confidence < 70 || confidence >=90)return false;break;case 'low':if(confidence >=70)return false;break;}}if(this.currentFilters.status && detection.status !==this.currentFilters.status){return false;}if(this.currentFilters.direction && detection.direction !==this.currentFilters.direction){return false;}if(this.currentFilters.speedMin && detection.speed < parseInt(this.currentFilters.speedMin)){return false;}if(this.currentFilters.speedMax && detection.speed > parseInt(this.currentFilters.speedMax)){return false;}if(this.currentFilters.dateFrom){const fromDate=new Date(this.currentFilters.dateFrom);if(detection.timestamp < fromDate)return false;}if(this.currentFilters.dateTo){const toDate=new Date(this.currentFilters.dateTo);toDate.setHours(23,59,59,999);if(detection.timestamp > toDate)return false;}return true;});this.updateTable();this.updateResultCount();}clearAllFilters(){this.currentFilters={search:'',camera:'',confidence:'',dateFrom:'',dateTo:'',status:'',direction:'',speedMin:'',speedMax:''};document.getElementById('smart-search').value='';document.getElementById('camera-filter').value='';document.getElementById('confidence-filter').value='';document.getElementById('status-filter').value='';document.getElementById('direction-filter').value='';document.getElementById('date-from').value='';document.getElementById('date-to').value='';document.getElementById('speed-min').value='';document.getElementById('speed-max').value='';document.querySelectorAll('.quick-filter-btn').forEach(btn=> btn.classList.remove('active'));this.applyFilters();}handleSort(column){if(this.currentSort.column===column){if(this.currentSort.direction===null){this.currentSort.direction='asc';}else if(this.currentSort.direction==='asc'){this.currentSort.direction='desc';}else{this.currentSort.direction=null;this.currentSort.column=null;}}else{this.currentSort.column=column;this.currentSort.direction='asc';}this.sortDetections();this.updateTable();this.updateSortIcons();}sortDetections(){if(!this.currentSort.column || !this.currentSort.direction){return;}this.filteredDetections.sort((a,b)=>{let aVal,bVal;switch(this.currentSort.column){case 'timestamp':aVal=new Date(a.timestamp).getTime();bVal=new Date(b.timestamp).getTime();break;case 'plate':aVal=a.plate_number.toLowerCase();bVal=b.plate_number.toLowerCase();break;case 'camera':aVal=a.camera_name.toLowerCase();bVal=b.camera_name.toLowerCase();break;case 'confidence':aVal=a.confidence;bVal=b.confidence;break;case 'vehicle':aVal=`${a.vehicle_color}${a.vehicle_type}`.toLowerCase();bVal=`${b.vehicle_color}${b.vehicle_type}`.toLowerCase();break;case 'status':aVal=a.status.toLowerCase();bVal=b.status.toLowerCase();break;default:return 0;}if(aVal < bVal)return this.currentSort.direction==='asc' ?-1:1;if(aVal > bVal)return this.currentSort.direction==='asc' ? 1:-1;return 0;});}updateSortIcons(){document.querySelectorAll('.sort-icon').forEach(icon=>{icon.className='fas fa-sort sort-icon';});if(this.currentSort.column && this.currentSort.direction){const activeHeader=document.querySelector(`[data-sort="${this.currentSort.column}"] .sort-icon`);if(activeHeader){activeHeader.className=`fas fa-sort-${this.currentSort.direction==='asc' ? 'up':'down'}sort-icon`;}}}updateTable(){const tbody=document.getElementById('detection-table-body');if(!tbody)return;tbody.innerHTML=this.filteredDetections.map(detection=> ` <tr data-detection-id="${detection.id}" ${this.selectedDetections.has(detection.id)? 'class="selected"':''}> <td class="checkbox-column"> <input type="checkbox" ${this.selectedDetections.has(detection.id)? 'checked':''}onchange="detectionsPage.handleRowSelect('${detection.id}',this.checked)"> </td> <td>${this.formatTimestamp(detection.timestamp)}</td> <td class="plate-number">${detection.plate_number}</td> <td>${detection.camera_name}</td> <td> <span class="confidence-badge ${this.getConfidenceClass(detection.confidence)}"> ${detection.confidence.toFixed(1)}% </span> </td> <td class="vehicle-info">${detection.vehicle_color}${detection.vehicle_type}</td> <td> <span class="status-badge ${detection.status}"> ${this.capitalizeFirst(detection.status)}</span> </td> <td class="actions-column"> <div class="row-actions"> <button class="row-action-btn view" onclick="detectionsPage.showDetails('${detection.id}')" title="View Details"> <i class="fas fa-eye"></i> </button> <button class="row-action-btn download" onclick="detectionsPage.downloadDetection('${detection.id}')" title="Download"> <i class="fas fa-download"></i> </button> <button class="row-action-btn flag" onclick="detectionsPage.toggleFlag('${detection.id}')" title="Flag/Unflag"> <i class="fas fa-flag"></i> </button> </div> </td> </tr> `).join('');}updateResultCount(){const header=document.querySelector('.detection-table-header h3');if(header){header.textContent=`Detection Results(${this.filteredDetections.length})`;}}handleSelectAll(checked){if(checked){this.filteredDetections.forEach(detection=>{this.selectedDetections.add(detection.id);});}else{this.selectedDetections.clear();}this.updateTable();this.updateBulkActions();}handleRowSelect(detectionId,checked){if(checked){this.selectedDetections.add(detectionId);}else{this.selectedDetections.delete(detectionId);}this.updateBulkActions();}updateBulkActions(){const bulkActions=document.getElementById('bulk-actions');if(bulkActions){bulkActions.style.display=this.selectedDetections.size > 0 ? 'flex':'none';}}showDetails(detectionId){const detection=this.detections.find(d=> d.id===detectionId);if(!detection)return;this.populateModal(detection);document.getElementById('detection-details-modal').style.display='flex';}populateModal(detection){document.getElementById('modal-plate-number').textContent=detection.plate_number;document.getElementById('modal-plate-overlay').textContent=detection.plate_number;const basicInfoGrid=document.getElementById('basic-info-grid');basicInfoGrid.innerHTML=` <div class="info-item"> <label>Timestamp:</label> <span>${this.formatTimestamp(detection.timestamp)}</span> </div> <div class="info-item"> <label>Camera:</label> <span>${detection.camera_name}</span> </div> <div class="info-item"> <label>Confidence:</label> <span class="confidence-badge ${this.getConfidenceClass(detection.confidence)}"> ${detection.confidence.toFixed(1)}% </span> </div> <div class="info-item"> <label>Status:</label> <span class="status-badge ${detection.status}">${this.capitalizeFirst(detection.status)}</span> </div> <div class="info-item"> <label>Processing Time:</label> <span>${detection.processing_time}ms</span> </div> `;const vehicleInfoGrid=document.getElementById('vehicle-info-grid');vehicleInfoGrid.innerHTML=` <div class="info-item"> <label>Vehicle Type:</label> <span>${detection.vehicle_type}</span> </div> <div class="info-item"> <label>Color:</label> <span>${detection.vehicle_color}</span> </div> <div class="info-item"> <label>Make/Model:</label> <span>${detection.vehicle_make}${detection.vehicle_model}</span> </div> <div class="info-item"> <label>Direction:</label> <span>${this.capitalizeFirst(detection.direction)}</span> </div> <div class="info-item"> <label>Speed:</label> <span>${detection.speed}mph</span> </div> `;const confidenceBreakdown=document.getElementById('confidence-breakdown');confidenceBreakdown.innerHTML=` <div class="confidence-item"> <label>Overall Confidence:</label> <div class="confidence-bar"> <div class="confidence-fill" style="width:${detection.confidence}%"></div> <span class="confidence-percent">${detection.confidence.toFixed(1)}%</span> </div> </div> <div class="confidence-item"> <label>Character Recognition:</label> <div class="confidence-bar"> <div class="confidence-fill" style="width:${detection.confidence-1.3}%"></div> <span class="confidence-percent">${(detection.confidence-1.3).toFixed(1)}%</span> </div> </div> <div class="confidence-item"> <label>Plate Detection:</label> <div class="confidence-bar"> <div class="confidence-fill" style="width:${Math.min(detection.confidence+1.3,99.8)}%"></div> <span class="confidence-percent">${Math.min(detection.confidence+1.3,99.8).toFixed(1)}%</span> </div> </div> `;}closeModal(){document.getElementById('detection-details-modal').style.display='none';}switchTab(tabName){document.querySelectorAll('.detection-tab').forEach(tab=> tab.classList.remove('active'));document.querySelectorAll('.tab-panel').forEach(panel=> panel.classList.remove('active'));document.querySelector(`[data-tab="${tabName}"]`).classList.add('active');document.getElementById(`${tabName}-tab`).classList.add('active');}exportCSV(){const detections=this.selectedDetections.size > 0 ? this.filteredDetections.filter(d=> this.selectedDetections.has(d.id)):this.filteredDetections;const csvContent=this.generateCSV(detections);this.downloadFile(csvContent,'detections.csv','text/csv');this.showToast(`CSV export completed. ${detections.length}detections exported.`,'success');}exportPDF(){const detections=this.selectedDetections.size > 0 ? this.filteredDetections.filter(d=> this.selectedDetections.has(d.id)):this.filteredDetections;this.showToast(`PDF export functionality would be implemented here. ${detections.length}detections selected.`,'info');}generateCSV(detections){const headers=['Timestamp','Plate Number','Camera','Vehicle','Confidence','Status','Direction','Speed'];const rows=detections.map(d=> [ this.formatTimestamp(d.timestamp),d.plate_number,d.camera_name,`${d.vehicle_color}${d.vehicle_type}${d.vehicle_make}${d.vehicle_model}`,`${d.confidence.toFixed(1)}%`,d.status,d.direction,`${d.speed}mph` ]);return [headers,...rows].map(row=> row.map(field=> `"${field}"`).join(',')).join('\n');}downloadFile(content,filename,contentType){const blob=new Blob([content],{type:contentType});const url=window.URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();window.URL.revokeObjectURL(url);document.body.removeChild(a);}formatTimestamp(timestamp){return new Date(timestamp).toLocaleString();}getConfidenceClass(confidence){if(confidence >=90)return 'high';if(confidence >=70)return 'medium';return 'low';}capitalizeFirst(str){return str.charAt(0).toUpperCase()+str.slice(1);}showToast(message,type='info'){const toast=document.createElement('div');toast.className=`toast toast-${type}`;toast.innerHTML=` <i class="fas ${type==='success' ? 'fa-check-circle':type==='error' ? 'fa-exclamation-circle':'fa-info-circle'}"></i> <span>${message}</span> <button class="toast-close" onclick="this.parentElement.remove()"> <i class="fas fa-times"></i> </button> `;let container=document.getElementById('toast-container');if(!container){container=document.createElement('div');container.id='toast-container';container.className='toast-container';document.body.appendChild(container);}container.appendChild(toast);setTimeout(()=>{if(toast.parentElement){toast.remove();}},5000);}downloadDetection(detectionId){const detection=this.detections.find(d=> d.id===detectionId);if(detection){const jsonContent=JSON.stringify(detection,null,2);this.downloadFile(jsonContent,`detection_${detection.plate_number}.json`,'application/json');this.showToast(`Detection ${detection.plate_number}downloaded.`,'success');}}toggleFlag(detectionId){const detection=this.detections.find(d=> d.id===detectionId);if(detection){detection.flagged=!detection.flagged;detection.status=detection.flagged ? 'flagged':'verified';this.updateTable();this.showToast(`Detection ${detection.plate_number}${detection.flagged ? 'flagged':'unflagged'}.`,'info');}}}export default DetectionsPage;